export const EINSATZ_BY_ID = Object.fromEntries(EINSAETZE.map((e) => [e.id, e]))
export const EINSATZ_BY_NAME = Object.fromEntries(EINSAETZE.map((e) => [e.name, e]))

// Ostersonntag (Gauß) für saisonale Einsätze
function ostern(jahr) {
  const a = jahr % 19, b = Math.floor(jahr / 100), c = jahr % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25)
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4
  const l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451)
  const monat = Math.floor((h + l - 7 * m + 114) / 31), tag = ((h + l - 7 * m + 114) % 31) + 1
  return new Date(jahr, monat - 1, tag)
}
const tage = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
const zwischen = (d, a, b) => d >= a && d <= tage(b, 1)

// Ist die Saison am (realen) Datum aktiv? Zeiträume: Weihnachten 1.–26.12., Silvester 27.12.–2.1., Halloween 24.10.–1.11.,
// Ostern ±7 Tage um Ostersonntag, Vatertag/Muttertag ±2 Tage, Sommer Juni–August, Fußball nie (kein Zeitraum).
export function saisonAktiv(saison, datum = new Date()) {
  if (!saison) return true
  const j = datum.getFullYear(), d = new Date(j, datum.getMonth(), datum.getDate())
  switch (saison) {
    case 'weihnachten': return zwischen(d, new Date(j, 11, 1), new Date(j, 11, 26))
    case 'silvester': return zwischen(d, new Date(j, 11, 27), new Date(j, 11, 31)) || zwischen(d, new Date(j, 0, 1), new Date(j, 0, 2))
    case 'halloween': return zwischen(d, new Date(j, 9, 24), new Date(j, 10, 1))
    case 'ostern': { const o = ostern(j); return zwischen(d, tage(o, -7), tage(o, 7)) }
    case 'vatertag': { const v = tage(ostern(j), 39); return zwischen(d, tage(v, -2), tage(v, 2)) }
    case 'muttertag': { const erster = new Date(j, 4, 1); const so = tage(erster, (7 - erster.getDay()) % 7 + 7); return zwischen(d, tage(so, -2), tage(so, 2)) }
    case 'sommer': return d.getMonth() >= 5 && d.getMonth() <= 7
    default: return false
  }
}
